sigmoid.ex:
import math
def sigmoid(x):
    return 1.0 / (1.0 + math.exp(-x))
print(sigmoid(0))             # 0.5
print(round(sigmoid(4), 3))   # 0.982

threshold.ex:
def threshold(x, threshold=0):
    if x < threshold:
        return 0
    else:
        return 1
print(threshold(-0.5), threshold(0), threshold(2))   # 0 1 1

relu.ex:
def relu(x):
    if x < 0:
        return 0
    else:
        return x
print(relu(-3), relu(2.5))   # 0 2.5

